head.script:
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 웹스퀘어5 에서 CheckCombobox_all 의 데이터를 확인한다. (코멘트확인)
    //1. Check the data of CheckCombobox_all in WebSquare 5. (Comment confirmation)
    //Verify step 1. Select all
    //Test step 2. 브라우저에서 전체 선택을 선택한다.
    //2. In the browser, select Select All.
    //Verify step 2. Full selection is displayed on the label.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox1_main_tbody').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('checkcombobox1_label').textContent == '전체선택'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
